const b=$input.first().json.body||$input.first().json;
const req=['siteId','conversationId','userId','message'];
const miss=req.filter(k=>!b[k]);
if(miss.length)throw new Error('Missing: '+miss.join(', '));
const rid=b.requestId||('req_'+Date.now()+'_'+Math.random().toString(36).slice(2,11));
return[{json:{siteId:b.siteId,conversationId:b.conversationId,userId:b.userId,message:b.message,pageUrl:b.pageUrl||null,uiContext:b.uiContext||{},requestId:rid}}];

const inp=$('Validate Input').item.json;
const siteArr=$input.first().json;
const site=Array.isArray(siteArr)?siteArr[0]:siteArr;
if(!site)throw new Error('Site not found');

const repoUrl=site.repo_url||'';
const match=repoUrl.match(/github\.com\/([^/]+)\/([^/]+)/);
const owner=match?match[1]:'';
const repo=match?match[2].replace(/\.git$/,''):'';

return [{
  json: {
    ...inp,
    site: {
      id: site.id,
      name: site.name,
      repo_url: site.repo_url,
      default_branch: site.default_branch || 'main',
      stack: site.stack || 'unknown',
      allowedPaths: ['**/*'],
      owner,
      repo
    },
    fileContents: {},
    filesToFetch: ['src/app/page.tsx','src/app/layout.tsx','src/app/globals.css'],
    owner,
    repo,
    branch: site.default_branch || 'main'
  }
}];

const ctx = $('Build Context').item.json;
const flyResp = $input.first().json;
return [{ json: { ...ctx, previewUrl: flyResp.previewUrl || '', previewStatus: flyResp.status || 'unknown' } }];

// FIXED: Prepare fetch with explicit path tracking
const ctx = $input.first().json;
const files = ctx.filesToFetch || [];
if (files.length === 0) {
  return [{ json: { ...ctx, fileContents: {}, skipFetch: true } }];
}
// Create items with explicit path tracking
return files.map((f, idx) => ({ 
  json: { 
    ...ctx, 
    currentFetchPath: f,
    fetchIndex: idx,
    totalFiles: files.length
  } 
}));

// FIXED: Properly merge file contents by tracking paths from Prepare Fetch
const prepareItems = $('Prepare Fetch').all();
const fetchItems = $input.all();
const originalCtx = $('Merge Fly Response').item.json;

const fileContents = {};

// Match each fetch response with its corresponding prepare item
for (let i = 0; i < prepareItems.length; i++) {
  const path = prepareItems[i].json.currentFetchPath;
  const fetchResp = fetchItems[i]?.json;

  if (!path) continue;

  // Handle both full response and direct response formats
  let content = null;
  if (fetchResp?.body?.content) {
    content = fetchResp.body.content;
  } else if (fetchResp?.content) {
    content = fetchResp.content;
  }

  if (content) {
    try {
      fileContents[path] = Buffer.from(content, 'base64').toString('utf8');
    } catch (e) {
      fileContents[path] = '// Error decoding file: ' + e.message;
    }
  }
}

return [{ json: { ...originalCtx, fileContents } }];

// FIXED: Robust create_file tool with better error handling
let input;
try { 
  input = typeof query === 'string' ? JSON.parse(query) : query; 
} catch (e) {
  return 'Error: Invalid JSON. Use {"filePath": "path/file.tsx", "content": "file content"}';
}

const { filePath, content } = input;
if (!filePath || typeof content !== 'string') {
  return 'Error: Both filePath and content are required';
}

// Get context from workflow - try multiple sources
let ctx;
try {
  ctx = $('Merge Files')?.item?.json || {};
} catch (e) {
  ctx = {};
}

const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || ctx.site?.default_branch || 'main';

if (!owner || !repo) {
  return 'Error: Missing repository info. Owner: ' + owner + ', Repo: ' + repo;
}

try {
  // First check if file exists to get its SHA
  let sha = null;
  try {
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
      headers: {
        'Authorization': 'Bearer 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',
        'Accept': 'application/vnd.github+json'
      }
    });
    sha = existing.sha;
  } catch (e) {
    // File doesn't exist, that's fine
  }

  const body = {
    message: sha ? `Update ${filePath}` : `Create ${filePath}`,
    content: Buffer.from(content).toString('base64'),
    branch: branch
  };
  if (sha) body.sha = sha;

  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  });

  return `Success: Created ${filePath}`;
} catch (e) {
  return `Error creating ${filePath}: ${e.message}`;
}

// FIXED: Simpler read_file that accepts just path string
let filePath = query;
if (typeof query === 'string' && query.trim().startsWith('{')) {
  try {
    const parsed = JSON.parse(query);
    filePath = parsed.filePath || parsed.path || query;
  } catch (e) {}
}

filePath = String(filePath).trim().replace(/["']/g, '');
if (!filePath) return 'Error: filePath is required';

// Get context from workflow
let ctx;
try {
  ctx = $('Merge Files')?.item?.json || {};
} catch (e) {
  ctx = {};
}

const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || ctx.site?.default_branch || 'main';

if (!owner || !repo) {
  return 'Error: Missing repository info';
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    }
  });

  if (response.content && response.encoding === 'base64') {
    return Buffer.from(response.content, 'base64').toString('utf8');
  }
  return 'Error: File not found or empty';
} catch (e) {
  return `Error reading ${filePath}: ${e.message}`;
}

// FIXED: list_files that works without any input
let ctx;
try {
  ctx = $('Merge Files')?.item?.json || {};
} catch (e) {
  ctx = {};
}

const owner = ctx.owner || ctx.site?.owner;
const repo = ctx.repo || ctx.site?.repo;
const branch = ctx.branch || ctx.site?.default_branch || 'main';

if (!owner || !repo) {
  return 'Error: Missing repository info';
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    }
  });

  if (!response.tree) return 'Error: Could not fetch repository tree';

  const files = response.tree
    .filter(f => f.type === 'blob')
    .map(f => f.path)
    .slice(0, 100);

  return JSON.stringify(files, null, 2);
} catch (e) {
  return `Error listing files: ${e.message}`;
}

// FIXED: Parse Plan that handles natural language responses
const ctx = $('Merge Files').item.json;
const raw = $('AI Plan').item.json;
let plan;
let out = '';

// Get the AI output text
if (raw?.output) {
  if (typeof raw.output === 'string') out = raw.output;
  else if (typeof raw.output === 'object') out = JSON.stringify(raw.output);
}
if (!out && raw?.text) out = String(raw.text);

// Collect files created via tool calls
const filesCreated = [];
const steps = raw?.intermediateSteps || [];
for (const step of steps) {
  const obs = step?.observation || step?.result || '';
  if (typeof obs === 'string' && obs.includes('Success: Created')) {
    const match = obs.match(/Created\s+([^\s]+)/);
    if (match) filesCreated.push(match[1].trim());
  }
}

// Check for any tool action that created files
for (const step of steps) {
  const action = step?.action;
  if (action?.tool === 'create_file' && action?.toolInput) {
    try {
      const input = typeof action.toolInput === 'string' ? JSON.parse(action.toolInput) : action.toolInput;
      if (input.filePath && !filesCreated.includes(input.filePath)) {
        // Check if the observation indicates success
        const obs = step?.observation || '';
        if (obs.includes('Success') || !obs.includes('Error')) {
          filesCreated.push(input.filePath);
        }
      }
    } catch (e) {}
  }
}

// Build the plan based on what happened
if (filesCreated.length > 0) {
  plan = {
    humanSummary: out || `Created/updated ${filesCreated.length} file(s): ${filesCreated.join(', ')}. Refresh to see changes!`,
    unifiedDiff: '',
    fileTargets: filesCreated.map(f => ({ path: f, action: 'create' })),
    warnings: []
  };
} else if (out) {
  // AI responded but didn't create files - might be asking for clarification
  plan = {
    humanSummary: out,
    unifiedDiff: '',
    fileTargets: [],
    warnings: []
  };
} else {
  plan = {
    humanSummary: 'I couldn\'t process that request. Please try again with more details.',
    unifiedDiff: '',
    fileTargets: [],
    warnings: ['No output from AI']
  };
}

// Ensure all fields have correct types
plan.warnings = Array.isArray(plan.warnings) ? plan.warnings : [];
plan.unifiedDiff = typeof plan.unifiedDiff === 'string' ? plan.unifiedDiff : '';
plan.fileTargets = Array.isArray(plan.fileTargets) ? plan.fileTargets : [];
plan.humanSummary = plan.humanSummary || 'Changes processed.';

return [{ json: { ...ctx, plan, filesCreated } }];

const ctx = $input.first().json;
if (!ctx?.site) throw new Error('Missing site');
if (!ctx?.plan) throw new Error('Missing plan');
return [{ json: ctx }];

const ctx = $('Guardrails').item.json;
const refreshResp = $input.first().json;
const filesChanged = ctx.filesCreated || [];
const refreshOk = refreshResp.ok !== false;

if (!refreshOk && refreshResp.error) {
  ctx.plan.warnings = ctx.plan.warnings || [];
  ctx.plan.warnings.push('Preview refresh note: ' + refreshResp.error);
}

return [{ json: { ...ctx, filesChanged, applyOk: true } }];
